"""Author the first player-facing V2 Earthworks Dig/Fill Enhanced Input assets.

Run only after the #1012 native gameplay tags have compiled. The script is idempotent,
adds one feature-owned InputConfig to FS_V2Foundation, and refuses to steal an existing
Foundation key mapping.
"""
from __future__ import annotations

import json
import os
import sys
from pathlib import Path

import unreal

_ASSET_HELPER_DIR = Path(unreal.Paths.project_dir()).resolve() / "scripts" / "v2" / "assets"
if str(_ASSET_HELPER_DIR) not in sys.path:
    sys.path.insert(0, str(_ASSET_HELPER_DIR))
import p3_binary_authoring_lock as authoring_lock

ISSUE = 1012
INPUT_ROOT = "/Game/V2/Input/Earthworks"
DIG_ACTION = f"{INPUT_ROOT}/IA_V2EarthworksDig"
FILL_ACTION = f"{INPUT_ROOT}/IA_V2EarthworksFill"
MAPPING_CONTEXT = f"{INPUT_ROOT}/IMC_V2Earthworks"
INPUT_CONFIG = f"{INPUT_ROOT}/IC_V2Earthworks"
FOUNDATION_EXPERIENCE = "/Game/V2/XP_V2Foundation"
FOUNDATION_FEATURE_SET = "/Game/V2/FS_V2Foundation"
DIG_TAG = "Input.Earthworks.Dig"
FILL_TAG = "Input.Earthworks.Fill"
DIG_KEY = "Z"
FILL_KEY = "X"
RECEIPT = os.path.join(unreal.Paths.project_saved_dir(), "Issue1012", "earthworks_input_authoring.json")


def require_asset(path):
    asset = unreal.load_asset(path)
    if not asset:
        raise RuntimeError("missing required asset: " + path)
    return asset


def soft_load(value):
    if not value:
        return None
    load_sync = getattr(value, "load_synchronous", None)
    return load_sync() if callable(load_sync) else value


def save(asset):
    if not unreal.EditorAssetLibrary.save_loaded_asset(asset, False):
        raise RuntimeError("failed to save asset: " + asset.get_path_name())


def create_asset(path, asset_class, factory):
    existing = unreal.load_asset(path)
    if existing:
        expected = asset_class.static_class().get_path_name()
        if existing.get_class().get_path_name() != expected:
            raise RuntimeError(f"existing asset has wrong class: {path}")
        return existing, False
    folder, name = path.rsplit("/", 1)
    asset = unreal.AssetToolsHelpers.get_asset_tools().create_asset(name, folder, asset_class, factory)
    if not asset:
        raise RuntimeError("failed to create asset: " + path)
    return asset, True


def create_data_asset(path, data_class):
    factory = unreal.DataAssetFactory()
    factory.set_editor_property("data_asset_class", data_class.static_class())
    return create_asset(path, data_class, factory)


def gameplay_tag(tag_name):
    tag = unreal.GameplayTag()
    tag.import_text(tag_name)
    actual = str(unreal.GameplayTagLibrary.get_tag_name(tag))
    if actual != tag_name:
        raise RuntimeError(f"native gameplay tag is not registered: {tag_name} (read back {actual})")
    return tag


def key_named(name):
    key = unreal.Key()
    key.set_editor_property("key_name", unreal.Name(name))
    return key


def key_name(key):
    return str(key.get_editor_property("key_name"))


def context_mappings(context):
    # UE 5.8 stores active mappings in DefaultKeyMappings. Keep the legacy
    # property fallback so the authoring script stays usable on older 5.x data.
    try:
        defaults = context.get_editor_property("default_key_mappings")
        return list(defaults.get_editor_property("mappings"))
    except Exception:
        return list(context.get_editor_property("mappings"))


def mapping_contexts(input_config):
    result = []
    for entry in list(input_config.get_editor_property("mapping_contexts")):
        context = soft_load(entry.get_editor_property("mapping_context"))
        if context:
            result.append(context)
    return result


def active_foundation_input_configs(experience, feature_set):
    configs = []
    default_config = soft_load(experience.get_editor_property("default_input_config"))
    if default_config:
        configs.append(default_config)
    for value in list(feature_set.get_editor_property("input_configs")):
        config = soft_load(value)
        if config and config not in configs:
            configs.append(config)
    return configs


def mapped_keys(input_configs, ignored_context_path):
    used = {}
    for input_config in input_configs:
        for context in mapping_contexts(input_config):
            if context.get_path_name() == ignored_context_path:
                continue
            for mapping in context_mappings(context):
                name = key_name(mapping.get_editor_property("key"))
                action = mapping.get_editor_property("action")
                used.setdefault(name, []).append(action.get_path_name() if action else "None")
    return used


def configure_action(action):
    action.set_editor_property("value_type", unreal.InputActionValueType.BOOLEAN)
    save(action)


def configure_mapping_context(context, dig_action, fill_action):
    context.unmap_all()
    context.map_key(dig_action, key_named(DIG_KEY))
    context.map_key(fill_action, key_named(FILL_KEY))
    save(context)


def configure_input_config(config, context, dig_action, fill_action):
    entry = unreal.P3InputMappingContextEntry()
    entry.set_editor_property("mapping_context", context)
    entry.set_editor_property("priority", 20)

    dig = unreal.P3InputActionBinding()
    dig.set_editor_property("input_tag", gameplay_tag(DIG_TAG))
    dig.set_editor_property("input_action", dig_action)

    fill = unreal.P3InputActionBinding()
    fill.set_editor_property("input_tag", gameplay_tag(FILL_TAG))
    fill.set_editor_property("input_action", fill_action)

    config.set_editor_property("mapping_contexts", [entry])
    config.set_editor_property("input_actions", [dig, fill])
    save(config)


def ensure_feature_registration(feature_set, input_config):
    configs = list(feature_set.get_editor_property("input_configs"))
    if not any(soft_load(value) == input_config for value in configs):
        configs.append(input_config)
        feature_set.set_editor_property("input_configs", configs)
        save(feature_set)


def verify_persisted(feature_set):
    dig_action = require_asset(DIG_ACTION)
    fill_action = require_asset(FILL_ACTION)
    context = require_asset(MAPPING_CONTEXT)
    config = require_asset(INPUT_CONFIG)

    mappings = context_mappings(context)
    pairs = {
        (m.get_editor_property("action").get_path_name(), key_name(m.get_editor_property("key")))
        for m in mappings
        if m.get_editor_property("action")
    }
    expected_pairs = {(dig_action.get_path_name(), DIG_KEY), (fill_action.get_path_name(), FILL_KEY)}
    if pairs != expected_pairs:
        raise RuntimeError(f"Earthworks IMC mappings did not persist: {sorted(pairs)}")

    bindings = list(config.get_editor_property("input_actions"))
    tags = {
        str(unreal.GameplayTagLibrary.get_tag_name(binding.get_editor_property("input_tag")))
        for binding in bindings
    }
    if tags != {DIG_TAG, FILL_TAG}:
        raise RuntimeError(f"Earthworks InputConfig tags did not persist: {sorted(tags)}")

    if not any(soft_load(value) == config for value in list(feature_set.get_editor_property("input_configs"))):
        raise RuntimeError("FS_V2Foundation did not persist IC_V2Earthworks")

    return {
        "issue": ISSUE,
        "dig": {"tag": DIG_TAG, "key": DIG_KEY, "action": dig_action.get_path_name()},
        "fill": {"tag": FILL_TAG, "key": FILL_KEY, "action": fill_action.get_path_name()},
        "mapping_context": context.get_path_name(),
        "input_config": config.get_path_name(),
        "feature_set": feature_set.get_path_name(),
    }


def _authoring_targets():
    return [DIG_ACTION, FILL_ACTION, MAPPING_CONTEXT, INPUT_CONFIG, FOUNDATION_FEATURE_SET]

def run():
    authoring_lock.ensure_package_locks(unreal.Paths.project_dir(), _authoring_targets())
    input_config_class = getattr(unreal, "P3InputConfig")
    experience = require_asset(FOUNDATION_EXPERIENCE)
    feature_set = require_asset(FOUNDATION_FEATURE_SET)

    active_configs = active_foundation_input_configs(experience, feature_set)
    used = mapped_keys(active_configs, MAPPING_CONTEXT)
    conflicts = {name: used[name] for name in (DIG_KEY, FILL_KEY) if name in used}
    if conflicts:
        raise RuntimeError("Earthworks key conflict in active Foundation input: " + json.dumps(conflicts, sort_keys=True))

    dig_action, _ = create_asset(DIG_ACTION, unreal.InputAction, unreal.InputAction_Factory())
    fill_action, _ = create_asset(FILL_ACTION, unreal.InputAction, unreal.InputAction_Factory())
    context, _ = create_asset(MAPPING_CONTEXT, unreal.InputMappingContext, unreal.InputMappingContext_Factory())
    config, _ = create_data_asset(INPUT_CONFIG, input_config_class)

    configure_action(dig_action)
    configure_action(fill_action)
    configure_mapping_context(context, dig_action, fill_action)
    configure_input_config(config, context, dig_action, fill_action)
    ensure_feature_registration(feature_set, config)

    receipt = verify_persisted(feature_set)
    os.makedirs(os.path.dirname(RECEIPT), exist_ok=True)
    with open(RECEIPT, "w", encoding="utf-8") as handle:
        json.dump(receipt, handle, indent=2, sort_keys=True)
        handle.write("\n")
    print("P3_ISSUE1012_EARTHWORKS_INPUT=" + json.dumps(receipt, sort_keys=True))
    return receipt


if __name__ == "__main__":
    run()

